<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderSamlIdpIdpCertAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderSamlIdpIdpCertAccessor trait.
 *
 * Covers null default, string/VO assignment via withSamlIdpIdpCert,
 * getSamlIdpIdpCert/samlIdpIdpCert accessors, and isSamlIdpIdpCertChanged with/without original.
 */
class TenantLoginProviderSamlIdpIdpCertAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSamlIdpIdpCert creates a new instance with the SamlIdpIdpCert set
     * from a string value, and getSamlIdpIdpCert returns the primitive string.
     */
    public function testWithSamlIdpIdpCertFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpIdpCertAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpIdpCert('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->getSamlIdpIdpCert());
    }
    /**
     * Asserts that withsamlIdpIdpCert has access to the value object
     * from a string value, and getSamlIdpIdpCert returns the primitive string.
     */
    public function testWithSamlIdpIdpCertFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpIdpCertAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpIdpCert('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->samlIdpIdpCert()->value());
    }
    public function testChangedSamlIdpIdpCert(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpIdpCertAccessorUnitTest();
        $original = $holder->withSamlIdpIdpCert('store://bin');
        $same = $holder->withSamlIdpIdpCert('store://bin');
        $modified = $holder->withSamlIdpIdpCert('store://obin');

        // Act
        $unchanged = $holder->isSamlIdpIdpCertChanged();
        $withSame = $original->isSamlIdpIdpCertChanged($same);
        $withDiferent = $original->isSamlIdpIdpCertChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderSamlIdpIdpCertAccessorUnitTest
{
    use TenantLoginProviderSamlIdpIdpCertAccessor;
}
